let pendingCheckout30=null;try{const saved=JSON.parse(localStorage.getItem('omega-checkout-pending')||'null');if(saved&&typeof saved.fingerprint==='string'&&typeof saved.key==='string')pendingCheckout30=saved}catch{};
async function checkout30(data){const fingerprint=JSON.stringify([user?.id,data.ids.slice().sort((a,b)=>a-b),data.code.trim().toUpperCase()]);if(!pendingCheckout30||pendingCheckout30.fingerprint!==fingerprint)pendingCheckout30={fingerprint,key:crypto.randomUUID()};localStorage.setItem('omega-checkout-pending',JSON.stringify(pendingCheckout30));const result=await api('checkout',data,{'Idempotency-Key':pendingCheckout30.key});pendingCheckout30=null;localStorage.removeItem('omega-checkout-pending');return result;}
const main=document.querySelector('#main'),nav=document.querySelector('#nav');let user=null,cart=readLocal("omega-cart",[]).filter(Number.isSafeInteger);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=v=>(v/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const feedback=document.createElement('div');feedback.id='feedback';feedback.setAttribute('aria-live','polite');document.body.append(feedback);
let pendingRequests=0;
function toast(message,type='success'){recordNotice(message,type);const el=document.createElement('div');el.className='toast '+type;el.setAttribute('role',type==='error'?'alert':'status');const mark=document.createElement('span');mark.className='toast-mark';mark.textContent=type==='error'?'!':type==='info'?'i':'✓';const txt=document.createElement('span');txt.textContent=message;const close=document.createElement('button');close.textContent='×';close.setAttribute('aria-label','Fechar aviso');close.onclick=()=>el.remove();el.append(mark,txt,close);feedback.append(el);setTimeout(()=>el.remove(),type==='error'?8500:4500)}
async function api(path,data,extraHeaders={}){pendingRequests++;document.body.classList.add('requesting');try{let r=await fetch('/api/'+path,{...(data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json',...extraHeaders},body:JSON.stringify(data)}),signal:AbortSignal.timeout(30000)});let j=await r.json();if(!r.ok)throw Error(j.error||'Falha na solicitação ('+r.status+').');return j}catch(e){if(e.name==='TimeoutError')throw Error('Tempo limite atingido. Confira o estado antes de tentar novamente.');if(e instanceof TypeError)throw Error('Sem conexão com o servidor. Confira sua conexão.');throw e}finally{if(--pendingRequests===0)document.body.classList.remove('requesting')}}
async function upload29(path,data,formId){const form=document.getElementById(formId);const status=document.createElement('div');status.className='upload29';status.setAttribute('role','status');const progress=document.createElement('progress');progress.max=100;progress.value=0;const label=document.createElement('span');label.textContent='Enviando… 0%';status.append(progress,label);form.append(status);try{return await new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open('POST','/api/'+path);x.setRequestHeader('Content-Type','application/json');x.timeout=120000;x.upload.onprogress=e=>{if(e.lengthComputable){progress.value=Math.floor(e.loaded/e.total*100);label.textContent='Enviando… '+progress.value+'%'}};x.upload.onload=()=>{progress.value=100;label.textContent='100% enviado — aguardando validação do servidor…'};x.onload=()=>{try{const j=JSON.parse(x.responseText);if(x.status<200||x.status>=300)throw Error(j.error||'Falha no upload');label.textContent='Arquivo recebido com sucesso';resolve(j)}catch(e){reject(e)}};x.onerror=()=>reject(Error('Falha de conexão durante o envio'));x.ontimeout=()=>reject(Error('Tempo limite atingido. Verifique se o arquivo foi recebido antes de repetir.'));x.onabort=()=>reject(Error('Envio interrompido'));x.send(JSON.stringify(data))})}catch(e){label.textContent=e.message;throw e}}
