let operationBusy=false;
async function perform(button,fn,message){if(operationBusy)return;operationBusy=true;const original=button?.innerHTML;const controls=[...main.querySelectorAll('button')].filter(b=>!b.disabled);controls.forEach(b=>b.disabled=true);if(button){button.setAttribute('aria-busy','true');button.innerHTML='<span class="omega-spinner" aria-hidden="true"></span> Processando…'}try{const result=await fn();if(result!==false&&message)toast(message)}catch(e){toast(e?.message||'Não foi possível concluir a operação.','error')}finally{operationBusy=false;controls.forEach(b=>b.disabled=false);if(button){button.removeAttribute('aria-busy');button.innerHTML=original}}}
function form(id,fn){document.getElementById(id).onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));await perform(e.submitter||e.target.querySelector('button'),()=>fn(data),formMessages[id]||'Operação concluída.')}}
