function flyToCart(button){const image=button.closest('article,.product-detail')?.querySelector('img');const target=nav.querySelector('a[href="#carrinho"]');if(!target)return;target.classList.add('cart-pulse');setTimeout(()=>target.classList.remove('cart-pulse'),600);if(!image||matchMedia('(prefers-reduced-motion: reduce)').matches||!image.animate)return;const a=image.getBoundingClientRect(),b=target.getBoundingClientRect();const clone=image.cloneNode();clone.className='cart-flight';Object.assign(clone.style,{left:a.left+'px',top:a.top+'px',width:a.width+'px',height:a.height+'px'});document.body.append(clone);const anim=clone.animate([{transform:'translate(0,0) scale(1)',opacity:.95},{transform:`translate(${b.left+b.width/2-a.left-a.width/2}px,${b.top+b.height/2-a.top-a.height/2}px) scale(.12)`,opacity:.15}],{duration:650,easing:'cubic-bezier(.3,.1,.3,1)'});anim.finished.then(()=>clone.remove(),()=>clone.remove())}
